import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
print("user_version:", con.execute("PRAGMA user_version").fetchone()[0])
tables = [t for (t,) in con.execute("select name from sqlite_master where type='table' order by name")]
print("table_count:", len(tables))
counts = {}
for t in tables:
    counts[t] = con.execute(f'select count(*) from "{t}"').fetchone()[0]
print("== NON-EMPTY TABLES ==")
for t in tables:
    if counts[t] > 0:
        print(f"{t}\t{counts[t]}")
print("== EMPTY TABLES ==")
empty = {t for t in tables if counts[t] == 0}
for t in tables:
    if counts[t] == 0:
        print(t)
print("empty_count:", len(empty))
print("== UNWRITABLE ==")
n=0
for t in tables:
    dead = {f[3] for f in con.execute(f'PRAGMA foreign_key_list("{t}")') if f[2] in empty}
    for c in con.execute(f'PRAGMA table_info("{t}")'):
        if c[1] in dead and c[3]:
            print(f"UNWRITABLE  {t}.{c[1]} -> empty table"); n+=1
print("unwritable_count:", n)
