import sqlite3
con = sqlite3.connect('file:data/guidebook.db?mode=ro', uri=True)
tables = [t for (t,) in con.execute("select name from sqlite_master where type='table'")]
ids=set()
for t in tables:
    for c in [r[1] for r in con.execute(f'PRAGMA table_info("{t}")')]:
        if 'session' in c.lower():
            ids |= {v for (v,) in con.execute(f'select distinct "{c}" from "{t}" where "{c}" is not null and "{c}" != \'\'')}
md=[i for i in ids if i.endswith('.md')]
print("ids_ending_.md:", len(md), sorted(md))
PY

